    def test_cancel_operation_updates_operation_and_action_without_module_side_effects(self) -> None:
        result = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-cancel"),
            input_payload={"filters": {"function_buckets": ["engineering"]}},
            idempotency_key="filter:proj-cancel",
        )
        operator_reason = "Operator requested cancellation — 操作员已确认"

        cancelled = self.writer.cancel_operation(
            operation_run_id=result.operation_run["operation_run_id"],
            actor="unit-test",
            reason=operator_reason,
        )
        duplicate = self.writer.cancel_operation(
            operation_run_id=result.operation_run["operation_run_id"],
            actor="unit-test",
            reason="ignored duplicate cancellation reason",
        )

        action = self.store.repos.workflow_runtime.get_action(result.action["action_id"])
        events = self.store.repos.workflow_runtime.list_operation_events(result.operation_run["operation_run_id"])
        self.assertEqual(cancelled["status"], "cancelled")
        self.assertEqual(duplicate["operation_run_id"], cancelled["operation_run_id"])
        self.assertEqual(cancelled["progress"]["phase"], "cancelled")
        self.assertEqual(cancelled["progress"]["reason"], "operation_cancelled")
        self.assertEqual(duplicate["progress"]["reason"], "operation_cancelled")
        self.assertEqual(action["status"], "cancelled")
        self.assertEqual(
            [event["event_type"] for event in events],
            ["OperationRunQueued", "OperationCancelled"],
        )
        self.assertEqual(events[-1]["payload"]["reason"], operator_reason)
        self.assertEqual(self.store.list_workflow_commands(limit=0), [])

    def test_reject_action_is_atomic_idempotent_and_repairs_missing_event(self) -> None:
        submitted = self.writer.submit_action(
            action_type=ACTION_EXPORT_CANDIDATES,
            workspace_id="default",
            owner_bound_target_ref=self._projection_export_owner_target("proj-reject"),
            input_payload={"include_crm_notes": True},
            idempotency_key="export:proj-reject",
        )

        rejected = self.writer.reject_action(
            action_id=submitted.action["action_id"],
            actor="unit-test",
            reason="operator_rejected",
        )
        duplicate = self.writer.reject_action(
            action_id=submitted.action["action_id"],
            actor="unit-test",
            reason="ignored_duplicate_reason",
        )

        self.assertEqual(rejected["status"], "cancelled")
        self.assertEqual(rejected["approval_status"], "rejected")
        self.assertEqual(duplicate["action_id"], rejected["action_id"])
        self.assertEqual(duplicate["metadata"]["rejection_reason"], "operator_rejected")
        self.assertEqual(
            [
                event["event_type"]
                for event in self.store.repos.workflow_runtime.list_operation_events(rejected["action_id"])
            ],
            ["ActionApprovalRequired", "ActionRejected"],
        )

        partial = self.writer.submit_action(
            action_type=ACTION_EXPORT_CANDIDATES,
            workspace_id="default",
            owner_bound_target_ref=self._projection_export_owner_target("proj-reject-repair"),
            input_payload={"include_crm_notes": True},
            idempotency_key="export:proj-reject-repair",
        )
        self.store.repos.workflow_runtime.update_action_state(
            partial.action["action_id"],
            status="cancelled",
            approval_status="rejected",
            metadata_patch={"rejection_reason": "legacy_partial"},
        )
        repaired = self.writer.reject_action(
            action_id=partial.action["action_id"],
            actor="unit-test",
            reason="legacy_partial",
        )
        self.assertEqual(repaired["approval_status"], "rejected")
        self.assertEqual(
            [
                event["event_type"]
                for event in self.store.repos.workflow_runtime.list_operation_events(partial.action["action_id"])
            ],
            ["ActionApprovalRequired", "ActionRejected"],
        )

    def test_cancel_operation_repairs_legacy_partial_state(self) -> None:
        submitted = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-cancel-repair"),
            idempotency_key="filter:proj-cancel-repair",
        )
        operation_run_id = submitted.operation_run["operation_run_id"]
        self._seed_brownfield_operation_progress(
            self.store,
            operation_run_id,
            status="cancelled",
            progress_patch={"phase": "cancelled", "reason": "legacy_partial"},
        )

        repaired = self.writer.cancel_operation(
            operation_run_id=operation_run_id,
            actor="unit-test",
            reason="legacy_partial",
        )

        linked_action = self.store.repos.workflow_runtime.get_action(submitted.action["action_id"])
        self.assertEqual(repaired["status"], "cancelled")
        self.assertEqual(linked_action["status"], "cancelled")
        self.assertEqual(linked_action["metadata"]["cancelled_operation_run_id"], operation_run_id)
        self.assertEqual(
            [
                event["event_type"]
                for event in self.store.repos.workflow_runtime.list_operation_events(operation_run_id)
            ],
            ["OperationRunQueued", "OperationCancelled"],
        )

    def test_operation_control_event_failure_rolls_back_state(self) -> None:
        reject_submission = self.writer.submit_action(
            action_type=ACTION_EXPORT_CANDIDATES,
            workspace_id="default",
            owner_bound_target_ref=self._projection_export_owner_target("proj-reject-rollback"),
            input_payload={"include_crm_notes": True},
            idempotency_key="export:proj-reject-rollback",
        )
        cancel_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-cancel-rollback"),
            idempotency_key="filter:proj-cancel-rollback",
        )
        adapter = self.store._control_plane_postgres

        with mock.patch.object(
            adapter,
            "_append_operation_event_with_cursor",
            side_effect=RuntimeError("injected-event-write-failure"),
        ):
            with self.assertRaisesRegex(RuntimeError, "injected-event-write-failure"):
                self.writer.reject_action(action_id=reject_submission.action["action_id"])
            with self.assertRaisesRegex(RuntimeError, "injected-event-write-failure"):
                self.writer.cancel_operation(operation_run_id=cancel_submission.operation_run["operation_run_id"])

        rejected_action = self.store.repos.workflow_runtime.get_action(reject_submission.action["action_id"])
        cancelled_operation = self.store.repos.workflow_runtime.get_operation(
            cancel_submission.operation_run["operation_run_id"]
        )
        linked_action = self.store.repos.workflow_runtime.get_action(cancel_submission.action["action_id"])
        self.assertEqual(rejected_action["status"], "approval_required")
        self.assertEqual(rejected_action["approval_status"], "required")
        self.assertEqual(cancelled_operation["status"], "queued")
        self.assertEqual(linked_action["status"], "queued")
        self.assertEqual(
            [
                event["event_type"]
                for event in self.store.repos.workflow_runtime.list_operation_events(rejected_action["action_id"])
            ],
            ["ActionApprovalRequired"],
        )
        self.assertEqual(
            [
                event["event_type"]
                for event in self.store.repos.workflow_runtime.list_operation_events(
                    cancelled_operation["operation_run_id"]
                )
            ],
            ["OperationRunQueued"],
        )

    def test_operation_control_rejects_cross_workspace_links_and_event_collisions(self) -> None:
        repository = self.store.repos.workflow_runtime
        repository.upsert_action(
            action_id="action-workspace-b",
            workspace_id="workspace-b",
            action_type="candidate.lookup",
            owner_module="operation_runtime",
            operation_type="projection.read",
            idempotency_key="action-workspace-b-idem",
            status="queued",
        )
        repository.upsert_operation(
            operation_run_id="operation-workspace-a",
            workspace_id="workspace-a",
            action_id="action-workspace-b",
            owner_module="operation_runtime",
            operation_type="projection.read",
            idempotency_key="operation-workspace-a-idem",
            status="queued",
        )
        with self.assertRaisesRegex(RuntimeError, "linked action workspace"):
            self.writer.cancel_operation(operation_run_id="operation-workspace-a")
        self.assertEqual(repository.get_operation("operation-workspace-a")["status"], "queued")
        self.assertEqual(repository.get_action("action-workspace-b")["status"], "queued")
        self.assertEqual(repository.list_operation_events("operation-workspace-a"), [])
        orchestrator = object.__new__(SourcingOrchestrator)
        orchestrator.store = self.store
        orchestrator._command_kernel = CommandKernel(self.store)
        public_run = orchestrator.get_operation_run_api("operation-workspace-a")["operation_run"]
        control_state = public_run["control_state"]
        self.assertEqual(control_state["allowed_actions"], [])
        self.assertFalse(control_state["can_dispatch"])
        self.assertFalse(control_state["can_resume"])
        self.assertFalse(control_state["can_retry"])
        self.assertFalse(control_state["can_cancel"])
        self.assertEqual(control_state["disabled_reasons"]["dispatch"], "linked_action_missing")
        self.assertEqual(control_state["disabled_reasons"]["resume"], "linked_action_missing")
        self.assertEqual(control_state["disabled_reasons"]["cancel"], "linked_action_missing")
        self.assertEqual(
            control_state["disabled_reasons"]["retry"],
            "retry_requires_failed_or_cancelled_operation",
        )

        submitted = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-event-collision"),
            idempotency_key="filter:proj-event-collision",
        )
        operation_run_id = submitted.operation_run["operation_run_id"]
        repository.append_operation_event(
            workspace_id="default",
            event_stream_id=operation_run_id,
            operation_run_id=operation_run_id,
            action_id=submitted.action["action_id"],
            event_family="operation_event",
            event_type="WrongCancellationEvent",
            idempotency_key=f"{submitted.operation_run['idempotency_key']}:OperationCancelled",
        )
        with self.assertRaisesRegex(RuntimeError, "event identity collision"):
            self.writer.cancel_operation(operation_run_id=operation_run_id)
        self.assertEqual(repository.get_operation(operation_run_id)["status"], "queued")
        self.assertEqual(repository.get_action(submitted.action["action_id"])["status"], "queued")
        self.assertNotIn(
            "OperationCancelled",
            [event["event_type"] for event in repository.list_operation_events(operation_run_id)],
        )

        event_row = repository._operation_event_row_payload(
            event_stream_id=operation_run_id,
            event_family="operation_event",
            event_type="OperationCancelled",
            idempotency_key="invalid-target-status",
            operation_run_id=operation_run_id,
            action_id=submitted.action["action_id"],
        )
        with self.assertRaisesRegex(ValueError, "only supports status=cancelled"):
            self.store._control_plane_postgres.cancel_operation_run_with_event(
                table_name="operation_runs",
                operation_run_id=operation_run_id,
                expected_status="queued",
                status="completed",
                event_row=event_row,
            )

        empty_status_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-empty-cancel-status"),
            idempotency_key="filter:proj-empty-cancel-status",
        )
        empty_status_event = repository._operation_event_row_payload(
            event_stream_id=empty_status_submission.operation_run["operation_run_id"],
            event_family="operation_event",
            event_type="OperationCancelled",
            idempotency_key="empty-cancel-status",
            operation_run_id=empty_status_submission.operation_run["operation_run_id"],
            action_id=empty_status_submission.action["action_id"],
        )
        empty_status_result = self.store._control_plane_postgres.cancel_operation_run_with_event(
            table_name="operation_runs",
            operation_run_id=empty_status_submission.operation_run["operation_run_id"],
            expected_status=empty_status_submission.operation_run["status"],
            status=" ",
            event_row=empty_status_event,
        )
        self.assertEqual(empty_status_result["outcome"], "applied")
        self.assertEqual(empty_status_result["operation"]["status"], "cancelled")

    def test_operation_control_cas_conflicts_do_not_report_success_or_append_events(self) -> None:
        repository = self.store.repos.workflow_runtime
        orchestrator = object.__new__(SourcingOrchestrator)
        orchestrator.store = self.store
        orchestrator._command_kernel = CommandKernel(self.store)
        orchestrator.operation_runtime_writer = self.writer

        reject_submission = self.writer.submit_action(
            action_type=ACTION_EXPORT_CANDIDATES,
            workspace_id="default",
            owner_bound_target_ref=self._projection_export_owner_target("proj-reject-race"),
            input_payload={"include_crm_notes": True},
            idempotency_key="export:proj-reject-race",
        )
        original_reject = repository.reject_action_with_event

        def complete_before_reject(*args: object, **kwargs: object) -> dict[str, object]:
            repository.update_action_state(reject_submission.action["action_id"], status="completed")
            return original_reject(*args, **kwargs)

        with mock.patch.object(repository, "reject_action_with_event", side_effect=complete_before_reject):
            reject_response = orchestrator.reject_operation_action_api(
                reject_submission.action["action_id"],
                {"actor": "unit-test", "reason": "lost-race"},
            )
        self.assertEqual(reject_response["status"], "conflict")
        self.assertEqual(reject_response["actual_status"], "completed")
        self.assertNotIn(
            "ActionRejected",
            [event["event_type"] for event in repository.list_operation_events(reject_submission.action["action_id"])],
        )

        cancel_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-cancel-race"),
            idempotency_key="filter:proj-cancel-race",
        )
        original_cancel = repository.cancel_operation_with_event

        def complete_before_cancel(*args: object, **kwargs: object) -> dict[str, object]:
            repository.update_operation_state(
                cancel_submission.operation_run["operation_run_id"],
                status="completed",
            )
            return original_cancel(*args, **kwargs)

        with mock.patch.object(repository, "cancel_operation_with_event", side_effect=complete_before_cancel):
            cancel_response = orchestrator.cancel_operation_run_api(
                cancel_submission.operation_run["operation_run_id"],
                {"actor": "unit-test", "reason": "lost-race"},
            )
        self.assertEqual(cancel_response["status"], "conflict")
        self.assertEqual(cancel_response["actual_status"], "completed")
        self.assertNotIn(
            "OperationCancelled",
            [
                event["event_type"]
                for event in repository.list_operation_events(cancel_submission.operation_run["operation_run_id"])
            ],
        )

    def test_stale_input_failure_uow_replays_and_rolls_back_as_one_transition(self) -> None:
        repository = self.store.repos.workflow_runtime
        submitted = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-stale-uow"),
            idempotency_key="filter:proj-stale-uow",
        )
        operation = submitted.operation_run
        action = submitted.action
        conflict_payload = {
            "phase": "reselection_required",
            "reason": "projection_membership_revision_stale",
            "projection_id": "proj-stale-uow",
            "expected_membership_revision": "revision-a",
            "membership_revision": "revision-b",
            "module_state_mutated": False,
        }
        transition_kwargs = {
            "expected_status": operation["status"],
            "action_id": action["action_id"],
            "workspace_id": "default",
            "progress_patch": conflict_payload,
            "progress_reason_owner": OPERATION_PROGRESS_REASON_OWNER_PROJECTION_RESELECTION,
            "result_ref_patch": conflict_payload,
            "metadata_patch": {"reselection_required": True, **conflict_payload},
            "linked_action_metadata_patch": {"reselection_required": True, **conflict_payload},
            "event_idempotency_key": (
                f"{operation['idempotency_key']}:OperationInputRevisionStale:revision-a:revision-b"
            ),
            "actor": "unit-test",
            "source": "test.operation_runtime",
            "event_payload": conflict_payload,
        }

        first = repository.fail_operation_for_stale_input_with_event(
            operation["operation_run_id"],
            **transition_kwargs,
        )
        replay = repository.fail_operation_for_stale_input_with_event(
            operation["operation_run_id"],
            **transition_kwargs,
        )

        self.assertEqual(first["outcome"], "applied")
        self.assertEqual(first["operation"]["status"], "failed")
        self.assertEqual(first["linked_action"]["status"], "failed")
        self.assertEqual(first["event"]["event_type"], "OperationInputRevisionStale")
        self.assertEqual(replay["outcome"], "already_applied")
        self.assertEqual(replay["event"]["event_id"], first["event"]["event_id"])
        self.assertEqual(
            [event["event_type"] for event in repository.list_operation_events(operation["operation_run_id"])].count(
                "OperationInputRevisionStale"
            ),
            1,
        )

        rollback_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-stale-uow-rollback"),
            idempotency_key="filter:proj-stale-uow-rollback",
        )
        rollback_operation = rollback_submission.operation_run
        rollback_action = rollback_submission.action
        rollback_kwargs = {
            **transition_kwargs,
            "expected_status": rollback_operation["status"],
            "action_id": rollback_action["action_id"],
            "event_idempotency_key": (
                f"{rollback_operation['idempotency_key']}:OperationInputRevisionStale:revision-a:revision-b"
            ),
        }
        with mock.patch.object(
            self.store._control_plane_postgres,
            "_append_operation_event_with_cursor",
            side_effect=RuntimeError("forced-stale-event-failure"),
        ):
            with self.assertRaisesRegex(RuntimeError, "forced-stale-event-failure"):
                repository.fail_operation_for_stale_input_with_event(
                    rollback_operation["operation_run_id"],
                    **rollback_kwargs,
                )
        self.assertEqual(
            repository.get_operation(rollback_operation["operation_run_id"])["status"],
            rollback_operation["status"],
        )
        self.assertEqual(
            repository.get_action(rollback_action["action_id"])["status"],
            rollback_action["status"],
        )
        self.assertNotIn(
            "OperationInputRevisionStale",
            [event["event_type"] for event in repository.list_operation_events(rollback_operation["operation_run_id"])],
        )

        action_conflict_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-stale-action-conflict"),
            idempotency_key="filter:proj-stale-action-conflict",
        )
        action_conflict_operation = action_conflict_submission.operation_run
        action_conflict_action = action_conflict_submission.action
        repository.update_operation_state(
            action_conflict_operation["operation_run_id"],
            status="failed",
            progress_patch=conflict_payload,
            progress_reason_owner=OPERATION_PROGRESS_REASON_OWNER_PROJECTION_RESELECTION,
            result_ref_patch=conflict_payload,
            metadata_patch={"reselection_required": True, **conflict_payload},
        )
        repository.update_action_state(action_conflict_action["action_id"], status="failed")
        action_conflict = repository.fail_operation_for_stale_input_with_event(
            action_conflict_operation["operation_run_id"],
            **{
                **transition_kwargs,
                "expected_status": action_conflict_operation["status"],
                "action_id": action_conflict_action["action_id"],
                "event_idempotency_key": "stale-action-metadata-conflict",
            },
        )
        self.assertEqual(action_conflict["outcome"], "conflict")
        self.assertEqual(action_conflict["operation"]["status"], "failed")
        self.assertEqual(action_conflict["linked_action"]["status"], "failed")
        self.assertEqual(action_conflict["linked_action"]["metadata"], action_conflict_action["metadata"])
        self.assertNotIn(
            "OperationInputRevisionStale",
            [
                event["event_type"]
                for event in repository.list_operation_events(action_conflict_operation["operation_run_id"])
            ],
        )

        event_conflict_submission = self.writer.submit_action(
            action_type=ACTION_FILTER_PROJECTION,
            workspace_id="default",
            owner_bound_target_ref=self._projection_read_owner_target("proj-stale-event-conflict"),
            idempotency_key="filter:proj-stale-event-conflict",
        )
        event_conflict_operation = event_conflict_submission.operation_run
        event_conflict_action = event_conflict_submission.action
        event_conflict_key = "stale-event-payload-conflict"
        repository.append_operation_event(
            workspace_id="default",
            event_stream_id=event_conflict_operation["operation_run_id"],
            operation_run_id=event_conflict_operation["operation_run_id"],
            action_id=event_conflict_action["action_id"],
            event_family="operation_event",
            event_type="OperationInputRevisionStale",
            idempotency_key=event_conflict_key,
            payload={**conflict_payload, "membership_revision": "different-revision"},
        )
        event_conflict = repository.fail_operation_for_stale_input_with_event(
            event_conflict_operation["operation_run_id"],
            **{
                **transition_kwargs,
                "expected_status": event_conflict_operation["status"],
                "action_id": event_conflict_action["action_id"],
                "event_idempotency_key": event_conflict_key,
            },
        )
        self.assertEqual(event_conflict["outcome"], "conflict")
        self.assertEqual(
            repository.get_operation(event_conflict_operation["operation_run_id"])["status"],
            event_conflict_operation["status"],
        )
        self.assertEqual(
            repository.get_action(event_conflict_action["action_id"])["status"],
            event_conflict_action["status"],
        )

